import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import { ComponentContext, getStudioProApi, IComponent, StudioProApi } from "@mendix/extensions-api";

import { Agent } from "../../types/agent";
import { KnowledgebaseTool } from "../../types/tool";

import AppThemeProvider from "../components/AppThemeProvider";

import { createStudioProLogger } from "../../config/logger";

import KnowledgebaseToolEditor from "./knowledgebaseToolEditor";

interface AppProps {
    studioPro: StudioProApi;
    initialTool?: KnowledgebaseTool;
    agent: Agent;
    onClose: (result: KnowledgebaseTool | null) => void;
}

const App: React.FC<AppProps> = ({ studioPro, initialTool, agent, onClose }) => {
    return (
        <AppThemeProvider studioPro={studioPro}>
            <KnowledgebaseToolEditor initialTool={initialTool} studioPro={studioPro} agent={agent} onClose={onClose} />
        </AppThemeProvider>
    );
};

export const component: IComponent = {
    async loaded(
        componentContext: ComponentContext,
        componentInput: { dialogId: string; agent: string; tool?: string }
    ) {
        const studioPro = getStudioProApi(componentContext);
        const logger = createStudioProLogger(studioPro);

        try {
            const rootElement = document.getElementById("root");
            if (!rootElement) {
                throw new Error("Failed to find the root element");
            }
            const root = createRoot(rootElement);

            let parsedTool: KnowledgebaseTool | undefined;
            if (componentInput.tool) {
                parsedTool = JSON.parse(decodeURIComponent(componentInput.tool));
            }

            const parsedAgent: Agent = JSON.parse(decodeURIComponent(componentInput.agent));

            const handleClose = (result: KnowledgebaseTool | null) => {
                studioPro.ui.dialogs.closeWithResult(componentInput.dialogId, result);
            };

            root.render(
                <StrictMode>
                    <App studioPro={studioPro} initialTool={parsedTool} agent={parsedAgent} onClose={handleClose} />
                </StrictMode>
            );
        } catch (error) {
            logger.error("Error editing agent knowledge base tool:", error);
            throw new Error("Error editing agent knowledge base tool:", error as Error);
        }
    },
};
